def apply_pair_fill2(grid, pair, source, target, zero_is_noop=True):
    out=[row[:] for row in grid]
    pts=set().union(*[set(s) for s in pair])
    rs=[r for r,c in pts]; cs=[c for r,c in pts]
    if not (zero_is_noop and target==0):
        for r in range(min(rs), max(rs)+1):
            for c in range(min(cs), max(cs)+1):
                out[r][c]=target
    for r,c in pts: out[r][c]=source
    return out
